// Writes the list of the events of triggers, from events.json, as Go for the manifest reader and the
// core. Run by `make lib_protocol_generate`; the generated file is committed.
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const read = (path) => readFileSync(fileURLToPath(new URL(path, import.meta.url)), 'utf8')
const write = (path, text) => writeFileSync(fileURLToPath(new URL(path, import.meta.url)), text)

const { events } = JSON.parse(read('../events.json'))
const HEADER =
  'Code generated by libs/core/protocol/tools/events.mjs from libs/core/protocol/events.json. DO NOT EDIT.'

/** The Go identifier of an event: EventFileAdded for file.added. */
const getGoName = (name) =>
  'Event' +
  name
    .split('.')
    .map((part) => part[0].toUpperCase() + part.slice(1))
    .join('')

const go = [
  `// ${HEADER}`,
  '',
  'package manifest',
  '',
  ...events.flatMap((one) => [
    `// ${getGoName(one.name)} is the event raised when ${one.about}.`,
    `const ${getGoName(one.name)} = ${JSON.stringify(one.name)}`,
    '',
  ]),
  '// IsEvent reports whether the name is an event a trigger runs on.',
  'func IsEvent(name string) bool {',
  '\tswitch name {',
  `\tcase ${events.map((one) => getGoName(one.name)).join(', ')}:`,
  '\t\treturn true',
  '\t}',
  '\treturn false',
  '}',
  '',
].join('\n')

write('../../../plugin/catalog/manifest/events.go', go)
